function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      const userSelect = container.querySelector('#select-user');
      if (users) {
        users.forEach(user => {
          const option = document.createElement('option');
          option.value = user.ユーザーID;
          option.textContent = user.ユーザー名 || user.ログインID;
          userSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 履歴一覧を描画する関数
  function renderHistories(histories) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => `
      <tr data-id="${history.操作履歴ID || ''}">
        <td>${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}</td>
        <td>${history.ユーザー名 || ''}</td>
        <td>${history.操作種別 || ''}</td>
        <td>${history.操作画面 || ''}</td>
        <td>${history.IPアドレス || ''}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                       background: ${history.処理結果 === '成功' ? 'var(--primary)' : history.処理結果 === '失敗' || history.処理結果 === 'エラー' ? '#dc3545' : '#6c757d'}; 
                       color: white;">
            ${history.処理結果 || ''}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID || ''}">詳細</button>
        </td>
      </tr>
    `).join('');

    updatePagination(histories.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages || totalPages === 0;
  }

  // 検索フィルター適用
  function applyFilters() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const userId = container.querySelector('#select-user').value;
    const operationType = container.querySelector('#select-operation-type').value;
    const screenName = container.querySelector('#input-screen-name').value.toLowerCase();
    const ipAddress = container.querySelector('#input-ip-address').value;
    const result = container.querySelector('#select-result').value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert('不正なIPアドレス形式です。正しい形式で入力してください。');
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const historyDate = new Date(history.操作日時);
        if (startDate && historyDate < new Date(startDate)) return false;
        if (endDate && historyDate > new Date(endDate + ' 23:59:59')) return false;
      }

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && !history.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && history.IPアドレス !== ipAddress) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // IPアドレス形式チェック
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    content.innerHTML = `
      <div style="display: grid; gap: 1rem;">
        <div><strong>操作履歴ID:</strong> ${history.操作履歴ID || ''}</div>
        <div><strong>操作日時:</strong> ${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}</div>
        <div><strong>ユーザー名:</strong> ${history.ユーザー名 || ''}</div>
        <div><strong>操作種別:</strong> ${history.操作種別 || ''}</div>
        <div><strong>操作画面:</strong> ${history.操作画面 || ''}</div>
        <div><strong>操作対象テーブル:</strong> ${history.操作対象テーブル || ''}</div>
        <div><strong>操作対象ID:</strong> ${history.操作対象ID || ''}</div>
        <div><strong>操作内容:</strong> ${history.操作内容 || ''}</div>
        <div><strong>IPアドレス:</strong> ${history.IPアドレス || ''}</div>
        <div><strong>ユーザーエージェント:</strong> ${history.ユーザーエージェント || ''}</div>
        <div><strong>処理結果:</strong> ${history.処理結果 || ''}</div>
        <div><strong>エラーメッセージ:</strong> ${history.エラーメッセージ || ''}</div>
        <div><strong>処理時間:</strong> ${history.処理時間 || ''}ms</div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // CSV出力
  function exportCSV() {
    if (filteredHistories.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    // 大量データの場合の警告
    if (filteredHistories.length > 100000) {
      alert('データ量が多すぎるため、CSV出力に失敗しました。検索条件を絞り込んでください。');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作内容', 'IPアドレス', '処理結果'];
    const csvContent = [
      headers.join(','),
      ...filteredHistories.map(history => [
        `"${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}"`,
        `"${history.ユーザー名 || ''}"`,
        `"${history.操作種別 || ''}"`,
        `"${history.操作画面 || ''}"`,
        `"${(history.操作内容 || '').replace(/"/g, '""')}"`,
        `"${history.IPアドレス || ''}"`,
        `"${history.処理結果 || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const histories = await window.aivicApi.list(13); // システム操作履歴テーブル
      if (histories) {
        allHistories = histories.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredHistories = [...allHistories];
        renderHistories(filteredHistories);
      } else {
        allHistories = tables[13]?.records || [];
        filteredHistories = [...allHistories];
        renderHistories(filteredHistories);
      }
    } catch (error) {
      console.error('操作履歴の取得に失敗しました:', error);
      allHistories = tables[13]?.records || [];
      filteredHistories = [...allHistories];
      renderHistories(filteredHistories);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-user').value = '';
    container.querySelector('#select-operation-type').value = '';
    container.querySelector('#input-screen-name').value = '';
    container.querySelector('#input-ip-address').value = '';
    container.querySelector('#select-result').value = '';
    filteredHistories = [...allHistories];
    currentPage = 1;
    renderHistories(filteredHistories);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#detail-modal')) {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 初期化
  loadUsers();
  loadInitialData();
}
